@Service
public class KYCDocumentService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public KYCDocumentService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new KYCDocumentEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(KYCDocumentRepository.class) );
		this.validator		= applicationContext.getBean(KYCDocumentValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		KYCDocument
	 */
		public KYCDocument createKYCDocument( CreateKYCDocumentCommand command ) {

		KYCDocument entity = new KYCDocument();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setKYCDocumentId( command.getKYCDocumentId() );
            entity.setReference( command.getReference() );
            entity.setIssuedCountry( command.getIssuedCountry() );
            entity.setExpirationDate( command.getExpirationDate() );
            entity.setDocumentType( command.getDocumentType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of KYCDocument {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateKYCDocumentCommand
	 * @return		KYCDocument
	 */
	public KYCDocument updateKYCDocument( UpdateKYCDocumentCommand command ) {

		KYCDocument entity = new KYCDocument();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setKYCDocumentId( command.getKYCDocumentId() );
            entity.setReference( command.getReference() );
            entity.setIssuedCountry( command.getIssuedCountry() );
            entity.setExpirationDate( command.getExpirationDate() );
            entity.setKycProfile( command.getKycProfile() );
            entity.setDocumentType( command.getDocumentType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of KYCDocument {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteKYCDocumentCommand
	 */
	public void delete( DeleteKYCDocumentCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getKYCDocumentId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of KYCDocument {0} ", id );

	}

	/**
	 * Method to retrieve the KYCDocument via KYCDocumentFetchOneSummary
	 * @param 	summary KYCDocumentFetchOneSummary
	 * @return 	KYCDocumentFetchOneResponse
	 */
	public KYCDocument getKYCDocument( KYCDocumentFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "KYCDocumentFetchOneSummary arg cannot be null" );

		KYCDocument entity = null;
		UUID id = summary.getKYCDocumentId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a KYCDocument using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all KYCDocuments
	 *
	 * @return 	List<KYCDocument>
	 */
    public List<KYCDocument> getAllKYCDocument() {
		List<KYCDocument> list = projector.findAll( new FindAllKYCDocumentQuery() );
		return list;
	}

	/**
	 * assign KycProfile on KYCDocument
	 * @param		command AssignKycProfileToKYCDocumentCommand
	 */
	public void assignKycProfile( AssignKycProfileToKYCDocumentCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignKycProfile(command.getKYCDocumentId(), command.getAssignment());

	}

	/**
	 * unAssign KycProfile on KYCDocument
	 * @param		command UnAssignKycProfileFromKYCDocumentCommand
	 */
	public void unAssignKycProfile( UnAssignKycProfileFromKYCDocumentCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignKycProfile(command.getKYCDocumentId());
	}
	




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final KYCDocumentEntityProjector projector;
	private final KYCDocumentValidator validator;
	private KYCDocument kYCDocument 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(KYCDocumentService.class);
}
